            var observationCommentSeen = false;
            CommentForm? varComment = null;
            var varCommentSeen = false;
            string? freeFormComment = null;
            var freeFormCommentSeen = false;
            string? uRI = null;
            var uRISeen = false;
            var scope = r.Enter();
            while (r.NextChild(ref scope))
            {
                switch (r.LocalName)
