                    case "WarningComment" when r.InNamespace(XmlNamespaces.Seismology): r.Once(ref warningCommentSeen, "WarningComment"); warningComment = global::JmaXml.Seismology.CommentForm.Read(r); break;
                    case "ForecastComment" when r.InNamespace(XmlNamespaces.Seismology): r.Once(ref forecastCommentSeen, "ForecastComment"); forecastComment = global::JmaXml.Seismology.CommentForm.Read(r); break;
                    case "ObservationComment" when r.InNamespace(XmlNamespaces.Seismology): r.Once(ref observationCommentSeen, "ObservationComment"); observationComment = global::JmaXml.Seismology.CommentForm.Read(r); break;
                    case "VarComment" when r.InNamespace(XmlNamespaces.Seismology): r.Once(ref varCommentSeen, "VarComment"); varComment = global::JmaXml.Seismology.CommentForm.Read(r); break;
                    case "FreeFormComment" when r.InNamespace(XmlNamespaces.Seismology): r.Once(ref freeFormCommentSeen, "FreeFormComment"); freeFormComment = r.ReadString(); break;
                    case "URI" when r.InNamespace(XmlNamespaces.Seismology): r.Once(ref uRISeen, "URI"); uRI = r.ReadString(); break;
