                ForecastComment = forecastComment,
                ObservationComment = observationComment,
                VarComment = varComment,
                FreeFormComment = freeFormComment,
                Uri = uRI,
            };
        }
    }

    /// <summary>各種付加文の要素を示す</summary>
    public sealed record CommentForm
    {
        /// <summary>コード種別</summary>
        public required string CodeType { get; init; }

        /// <summary>付加文内容</summary>
        /// <remarks>
        /// <para>付加文を示す</para>
        /// </remarks>
        public required string Text { get; init; }

        /// <summary>付加文コード</summary>
        /// <remarks>
        /// <para>付加文コードを示す。複数表記の場合はxs:list型を用いること。</para>
        /// </remarks>
        public required ImmutableArray<string> Code { get; init; }

        internal static CommentForm Read(JmaXmlReader r)
        {
            var codeType = r.RequiredAttributeString("codeType");
            string? text = null;
            var textSeen = false;
            ImmutableArray<string>? code = null;
            var codeSeen = false;
            var scope = r.Enter();
            while (r.NextChild(ref scope))
            {
                switch (r.LocalName)
                {
                    case "Text" when r.InNamespace(XmlNamespaces.Seismology): r.Once(ref textSeen, "Text"); text = r.ReadString(); break;
                    case "Code" when r.InNamespace(XmlNamespaces.Seismology): r.Once(ref codeSeen, "Code"); code = r.ReadList(); break;
                    default: r.Skip(); break;
                }
            }
            r.Exit(in scope);
            return new CommentForm
            {
                CodeType = codeType,
                Text = text ?? throw r.Missing(in scope, "Text"),
                Code = code ?? throw r.Missing(in scope, "Code"),
            };
        }
    }

    /// <summary>使うコード体系の定義</summary>
