        internal static CodeDefine Read(JmaXmlReader r)
        {
            ArrayBuilder<CodeDefineType> type = default;
            var scope = r.Enter();
            while (r.NextChild(ref scope))
            {
                switch (r.LocalName)
                {
                    case "Type" when r.InNamespace(XmlNamespaces.Seismology): type.Add(r, global::JmaXml.Seismology.CodeDefineType.Read(r)); break;
                    default: r.Skip(); break;
                }
            }
            r.Exit(in scope);
            return new CodeDefine
            {
                Type = type.IsEmpty ? throw r.Missing(in scope, "Type") : type.ToImmutable(r),
            };
        }
    }

    /// <summary>コード種別を示す</summary>
    public sealed record CodeDefineType
    {
        /// <summary>定義する相対xpath</summary>
        /// <remarks>
        /// <para>本要素の親要素からみた定義対象となる要素の相対xpathを記述する。</para>
